Rewrite the entire Node.js module below with these changes:
1) Add `touch(key, ttlMs?)` to refresh TTL without changing the value; return false if missing/expired.
2) Add `sweep()` that purges all expired keys and returns the count removed.
3) Add LRU eviction: constructor option `maxEntries`; on set, if over capacity, evict least-recently-used key (track lastAccess).
4) Make `get`/`set`/`touch` update lastAccess; include lastAccess in watcher events.
5) Export a small `demo()` function that shows touch, sweep, and eviction.
Return the FULL rewritten file only.

```javascript
// Simple in-memory KV with TTL, watchers, and batch ops.
class TtlStore {
  constructor(defaultTtlMs = 60000) {
    this.defaultTtlMs = defaultTtlMs;
    this.map = new Map(); // key -> { value, expiresAt }
    this.watchers = new Map(); // key -> Set<fn>
    this.hits = 0;
    this.misses = 0;
  }

  _now() { return Date.now(); }

  _purge(key) {
    const e = this.map.get(key);
    if (!e) return false;
    if (e.expiresAt !== null && e.expiresAt <= this._now()) {
      this.map.delete(key);
      this._notify(key, null, "expire");
      return true;
    }
    return false;
  }

  set(key, value, ttlMs = this.defaultTtlMs) {
    const expiresAt = ttlMs == null ? null : this._now() + ttlMs;
    this.map.set(key, { value, expiresAt });
    this._notify(key, value, "set");
    return value;
  }

  get(key) {
    this._purge(key);
    if (!this.map.has(key)) { this.misses++; return undefined; }
    this.hits++;
    return this.map.get(key).value;
  }

  del(key) {
    this._purge(key);
    const ok = this.map.delete(key);
    if (ok) this._notify(key, null, "del");
    return ok;
  }

  mget(keys) {
    const out = {};
    for (const k of keys) out[k] = this.get(k);
    return out;
  }

  mset(entries, ttlMs) {
    for (const [k, v] of Object.entries(entries)) this.set(k, v, ttlMs);
  }

  watch(key, fn) {
    if (!this.watchers.has(key)) this.watchers.set(key, new Set());
    this.watchers.get(key).add(fn);
    return () => this.watchers.get(key)?.delete(fn);
  }

  _notify(key, value, op) {
    const set = this.watchers.get(key);
    if (!set) return;
    for (const fn of set) {
      try { fn({ key, value, op, ts: this._now() }); } catch (_) {}
    }
  }

  stats() {
    return { size: this.map.size, hits: this.hits, misses: this.misses };
  }

  keys() {
    for (const k of [...this.map.keys()]) this._purge(k);
    return [...this.map.keys()];
  }
}

module.exports = { TtlStore };
```
